"""Legacy Meridian CRM numeric division semantics."""

from __future__ import annotations

from typing import Any


def _legacy_number(value: Any) -> float:
    """Coerce a legacy numeric value, treating empty or missing values as zero."""
    if value is None:
        return 0.0

    if isinstance(value, str):
        if value.strip() == "":
            return 0.0

    try:
        return float(value)
    except Exception:
        # Legacy numeric context treats values that cannot contribute a numeric
        # value as zero rather than allowing evaluation to raise.
        return 0.0


def safe_div(a: Any, b: Any) -> tuple[float, list[str]]:
    """Divide using CRMScript semantics, including audited division by zero."""
    numerator = _legacy_number(a)
    divisor = _legacy_number(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / divisor, []
    except Exception:
        # Preserve the legacy engine's non-raising behavior for unusual numeric
        # values while retaining the documented zero result and audit contract.
        return 0.0, ["SCRIPT_DIV0"]
